# Expected values generated by test/scipy/gen_optimize_global_expected.py (scipy 1.18.1).
import numpy as np
from scipy.optimize import (differential_evolution, basinhopping, dual_annealing,
                            direct, brute, shgo, rosen, show_options)

def close(x, ref, rtol: float = 1e-7, atol: float = 1e-10) -> bool:
    a = np.asarray(x, float)
    r = np.asarray(ref, float)
    if a.size != r.size:
        print('size', a.size, r.size)
        return False
    ok = True
    for u, v in zip(a.flat, r.flat):
        if abs(u - v) > atol + rtol * abs(v):
            print('mismatch', u, v)
            ok = False
    return ok

def check(cond: bool, what: str):
    if not cond:
        print('TEST FAILED:', what)

def ack(x):
    return -20.0*np.exp(-0.2*np.sqrt(0.5*(x[0]**2+x[1]**2))) - np.exp(0.5*(np.cos(2*np.pi*x[0])+np.cos(2*np.pi*x[1]))) + np.e + 20
def styb(x):
    return 0.5 * np.sum(x**4 - 16 * x**2 + 5 * x)
def ras(x):
    return np.sum(x * x - 10 * np.cos(2 * np.pi * x)) + 10 * np.size(x)
def bhf(x):
    return np.cos(14.5 * x[0] - 0.3) + (x[1] + 0.2) * x[1] + (x[0] + 0.2) * x[0]
def vr(x):
    return np.sum(x**2, axis=0)

def exact(r, x, fun: float, nit: int, nfev: int, what: str, rtol: float = 1e-12):
    check(close(r.x, x, rtol, 1e-14), what + ' x')
    check(close(r.fun, fun, rtol, 1e-14), what + ' fun')
    check(r.nit == nit, what + f' nit {r.nit} != {nit}')
    check(r.nfev == nfev, what + f' nfev {r.nfev} != {nfev}')

def test_de():
    exp = {'best1bin': (97, 3003), 'rand1exp': (164, 5013),
           'randtobest1bin': (108, 3333), 'best2exp': (165, 5043)}
    for st in ['best1bin', 'rand1exp', 'randtobest1bin', 'best2exp']:
        r = differential_evolution(ack, [(-5.0, 5.0)] * 2, strategy=st, rng=1, maxiter=200)
        e = exp[st]
        exact(r, [0.0, 0.0], 0.0, e[0], e[1], 'de ' + st)
        check(r.success, 'de success ' + st)
    r = differential_evolution(ack, [(-5.0, 5.0)] * 2, strategy='rand2bin', rng=1, maxiter=200)
    exact(r, [0.0, 1.1102230246251565e-15], 3.552713678800501e-15, 200, 6093, 'de rand2bin')
    check(not r.success and r.message == 'Maximum number of iterations has been exceeded.', 'de maxiter msg')
    r = differential_evolution(ack, [(-5.0, 5.0)] * 2, strategy='currenttobest1exp', rng=1, maxiter=200)
    exact(r, [0.0, 0.0], 0.0, 200, 6093, 'de currenttobest1exp')
    r = differential_evolution(rosen, [(0.0, 2.0)] * 3, rng=2, updating='deferred', polish=False)
    exact(r, [1.0, 1.0, 1.0], 0.0, 285, 12870, 'de deferred')
    r = differential_evolution(rosen, [(0.0, 2.0)] * 3, seed=5, init='random', mutation=0.6)
    exact(r, [1.0, 1.0, 1.0], 0.0, 179, 8104, 'de seed/random')
    r = differential_evolution(vr, [(-3.0, 3.0)] * 2, rng=4, vectorized=True)
    exact(r, [0.0, 0.0], 0.0, 125, 129, 'de vectorized')
    r = differential_evolution(rosen, [(-2.0, 2.0)] * 3, rng=6, integrality=[True, False, False], x0=[1.0, 1.0, 0.5])
    exact(r, [1.0, 1.0, 1.0], 0.0, 134, 6078, 'de integrality/x0')
    try:
        differential_evolution(rosen, [(0.0, 2.0)] * 2, strategy='nope')
        check(False, 'de bad strategy')
    except ValueError:
        pass

def test_bh_da():
    r = basinhopping(bhf, [1.0, 1.0], niter=60, rng=7)
    exact(r, [-0.19506755302699, -0.10000000757105626], -1.0108761844426555, 60, 1743, 'bh')
    r = basinhopping(bhf, [1.0, 1.0], niter=40, seed=3, niter_success=5, T=0.5)
    exact(r, [-0.1950675552233045, -0.10000000374447968], -1.0108761844426548, 10, 321, 'bh niter_success')
    check(r.message == 'success condition satisfied', 'bh message')
    r = dual_annealing(ras, [(-5.12, 5.12)] * 3, rng=42, maxiter=200)
    # x agrees to ~1e-9 (last-digit differences inside L-BFGS-B)
    check(close(r.x, [-0.9949586424917746, -4.8031366856915065e-09, -4.256802395333649e-09], 1e-7, 1e-8), 'da x')
    check(close(r.fun, 0.994959057093304, 1e-12), 'da fun')
    check(r.nit == 200 and r.nfev == 1397, f'da nit/nfev {r.nit} {r.nfev}')
    r = dual_annealing(ras, [(-5.12, 5.12)] * 3, seed=1, maxiter=150, no_local_search=True)
    exact(r, [-0.009784176680182277, 0.025311293515122735, -0.007399145430372123], 0.1566815131339716, 150, 901, 'da no_local_search')

def test_direct_brute():
    r = direct(styb, [(-4.0, 4.0)] * 3, locally_biased=True)
    exact(r, [-2.904435299497028] * 3, -117.49845496131213, 187, 3009, 'direct lb')
    check(r.status == 1 and r.message == 'Number of function evaluations done is larger than maxfun=3000', 'direct msg')
    r = direct(styb, [(-4.0, 4.0)] * 3, locally_biased=False)
    exact(r, [-2.904435299497028, -2.9080932784636486, -2.9080932784636486], -117.49776309019815, 26, 3069, 'direct orig')
    r = direct(rosen, [(-2.0, 2.0)] * 4, maxfun=3000, vol_tol=1e-30, eps=-1e-3)
    exact(r, [0.9999479402856246, 0.9999153245609569, 0.9998375486021334, 0.9996794877825881], 8.072194302713743e-08, 127, 2985, 'direct eps')
    check(r.status == 5 and r.success, 'direct len_tol')
    r = direct(rosen, [(-2.0, 3.0)] * 2, maxiter=20, f_min=0.0, f_min_rtol=1e-2)
    exact(r, [1.0555555555555558, 1.1172839506172845], 0.00403901844231066, 7, 59, 'direct f_min')
    check(r.status == 3, 'direct f_min status')
    x0, fv, g, J = brute(styb, (slice(-4.0, 4.0, 0.25), slice(-4.0, 4.0, 0.25)), full_output=True, finish=None)
    check(close(x0, [-3.0, -3.0]) and close(fv, -78.0) and J.size == 1024, 'brute grid')
    x0, fv, g, J = brute(styb, ((-4.0, 4.0), (-3.0, 3.0)), Ns=15, full_output=True)
    check(close(x0, [-2.903551196738526, -2.9035024830663936], 1e-12) and close(fv, -78.33233138523963, 1e-12), 'brute fmin')
    check(len(show_options(disp=False)) > 0, 'show_options')

def test_shgo():
    # sampling (nfev - nlfev), nit and the set of local minima match scipy;
    # local SLSQP runs agree to ~1e-8
    r = shgo(rosen, [(0.0, 2.0)] * 3)
    check(close(r.x, [1.0, 1.0, 1.0], 0.0, 1e-8) and r.fun < 1e-14, 'shgo rosen')
    check(r.nit == 1 and r.nfev - r.nlfev == 9 and r.xl.shape[0] == 1 and r.success, 'shgo rosen counts')
    r = shgo(styb, [(-4.0, 4.0)] * 3, n=30, iters=2)
    check(close(r.fun, -117.49849711131425, 1e-12), 'shgo styb fun')
    check(close(r.x, [-2.9035340210823413, -2.9035340256377946, -2.9035340392383535], 0.0, 1e-7), 'shgo styb x')
    check(r.nit == 2 and r.nfev - r.nlfev == 60 and r.xl.shape[0] == 11, f'shgo styb counts {r.nfev - r.nlfev} {r.xl.shape[0]}')
    check(close(r.funl, [-117.49849711131425, -117.49849711131407, -103.36177806282677, -103.36177806282676, -103.36177806282674, -103.36177806282646, -97.33233140754282, -89.22505901433931, -89.22505901433931, -89.22505901433912, -75.08833996585179], 1e-11), 'shgo funl')
    r = shgo(styb, [(-4.0, 4.0)] * 2, n=None, iters=3)
    check(close(r.fun, -78.33233140754285, 1e-12) and r.nit == 3 and r.nfev - r.nlfev == 41 and r.xl.shape[0] == 9, 'shgo n=None')

test_de()
test_bh_da()
test_direct_brute()
test_shgo()
print('done')
